{"source": "def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, instrument, channel_mode):
        # put_mode: 0=IGNORE, 1=REPLACE, 2=UPSERT
        # instrument: 0=none, 1=AFTER INSERT trigger
        # channel_mode: 0=main changes(), 1=main total_changes, 2=main+other total_changes
        items = {}
        log = []
        main_changes = 0
        main_total = 0
        other_total = 0
        in_tx = {"main": False, "other": False}
        tx_items = {"main": None, "other": None}
        tx_log = {"main": None, "other": None}
        tx_changes = {"main": 0, "other": 0}
        tx_total = {"main": 0, "other": 0}

        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            cur = items if not in_tx[conn] else tx_items[conn]
            cur_log = log if not in_tx[conn] else tx_log[conn]
            changed = 0
            inserted = False
            if put_mode == 0:
                if key not in cur:
                    cur[key] = value
                    changed = 1
                    inserted = True
            elif put_mode == 1:
                if key in cur:
                    cur[key] = value
                    changed = 1
                else:
                    cur[key] = value
                    changed = 1
                    inserted = True
            else:
                if key in cur:
                    cur[key] = value
                    changed = 1
                else:
                    cur[key] = value
                    changed = 1
                    inserted = True
            if instrument == 1 and inserted:
                cur_log.append(key)
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_total += changed

        def do_update(conn, key, value):
            nonlocal main_changes, main_total, other_total
            cur = items if not in_tx[conn] else tx_items[conn]
            changed = 0
            if key in cur:
                cur[key] = value
                changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_total += changed

        def do_delete(conn, key):
            nonlocal main_changes, main_total, other_total
            cur = items if not in_tx[conn] else tx_items[conn]
            changed = 0
            if key in cur:
                del cur[key]
                changed = 1
            if conn == "main":
                main_changes = changed
                main_total += changed
            else:
                other_total += changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_put(conn, act["key"], act["value"])
            elif op == "update":
                do_update(conn, act["key"], act["value"])
            elif op == "delete":
                do_delete(conn, act["key"])
            elif op == "begin":
                in_tx[conn] = True
                tx_items[conn] = dict(items)
                tx_log[conn] = list(log)
                tx_changes[conn] = 0
                tx_total[conn] = 0
            elif op == "commit":
                if in_tx[conn]:
                    items = tx_items[conn]
                    log = tx_log[conn]
                    in_tx[conn] = False
                    tx_items[conn] = None
                    tx_log[conn] = None
            elif op == "rollback":
                if in_tx[conn]:
                    in_tx[conn] = False
                    tx_items[conn] = None
                    tx_log[conn] = None

        if channel_mode == 0:
            ch = main_changes
        elif channel_mode == 1:
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(items), sum(items.values())

    candidates = []
    for pm in range(3):
        for inst in range(2):
            for cm in range(3):
                ok = True
                for rec in history:
                    ch, cc, cs = simulate(rec["actions"], pm, inst, cm)
                    obs = rec["observed"]
                    if ch != obs["channel"] or cc != obs["committed_count"] or cs != obs["committed_sum"]:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, inst, cm))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for pm, inst, cm in candidates:
        ch, cc, cs = simulate(actions, pm, inst, cm)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cc)
        elif goal == "committed_sum":
            results.add(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
", "scope": "Family-consistent simulation over put mode, trigger instrumentation, and channel counter; answer only when all consistent members agree.", "lesson": "Calibration receipts constrain the 18-member family; simulate each candidate and intersect predictions for the queried sequence."}
